-- ADR-001 (accepted 2026-10-27): first-party authentication. Tables/columns generated by prisma migrate diff;
-- the security section at the end is hand-written.

-- AlterTable
ALTER TABLE "app"."app_session" ADD COLUMN     "last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- AlterTable
ALTER TABLE "app"."app_user" ADD COLUMN     "password_hash" TEXT,
ADD COLUMN     "requires_totp" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "totp_last_step" BIGINT,
ADD COLUMN     "totp_secret_enc" TEXT;

-- CreateTable
CREATE TABLE "app"."auth_throttle" (
    "login_key" TEXT NOT NULL,
    "failures" INTEGER NOT NULL DEFAULT 0,
    "locked_until" TIMESTAMPTZ,

    CONSTRAINT "auth_throttle_pkey" PRIMARY KEY ("login_key")
);

-- CreateTable
CREATE TABLE "app"."auth_ip_attempt" (
    "id" BIGSERIAL NOT NULL,
    "ip" TEXT NOT NULL,
    "at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "auth_ip_attempt_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "app"."auth_challenge" (
    "token_hash" BYTEA NOT NULL,
    "user_id" UUID NOT NULL,
    "kind" TEXT NOT NULL,
    "pending_secret_enc" TEXT,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "used_at" TIMESTAMPTZ,

    CONSTRAINT "auth_challenge_pkey" PRIMARY KEY ("token_hash")
);

-- CreateTable
CREATE TABLE "app"."auth_recovery_code" (
    "user_id" UUID NOT NULL,
    "code_hash" BYTEA NOT NULL,
    "used_at" TIMESTAMPTZ,

    CONSTRAINT "auth_recovery_code_pkey" PRIMARY KEY ("user_id","code_hash")
);

-- CreateTable
CREATE TABLE "app"."auth_reset" (
    "token_hash" BYTEA NOT NULL,
    "user_id" UUID NOT NULL,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "used_at" TIMESTAMPTZ,

    CONSTRAINT "auth_reset_pkey" PRIMARY KEY ("token_hash")
);

-- CreateIndex
CREATE INDEX "auth_ip_attempt_ip_at_idx" ON "app"."auth_ip_attempt"("ip", "at");

-- AddForeignKey
ALTER TABLE "app"."auth_challenge" ADD CONSTRAINT "auth_challenge_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "app"."app_user"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "app"."auth_recovery_code" ADD CONSTRAINT "auth_recovery_code_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "app"."app_user"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "app"."auth_reset" ADD CONSTRAINT "auth_reset_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "app"."app_user"("id") ON DELETE CASCADE ON UPDATE CASCADE;


-- ---------- Security (hand-written) ----------
alter table app.auth_challenge add constraint auth_challenge_kind check (kind in ('enrol', 'totp'));

-- gems_auth runs authentication before any session exists, so RLS scope cannot apply to it:
-- it gets only the columns and tables auth needs. Hosted environments set LOGIN + password out of band.
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'gems_auth') then
    create role gems_auth nologin nosuperuser nocreatedb nocreaterole nobypassrls noinherit;
  end if;
end $$;
grant usage on schema app to gems_auth;
grant select on app.app_user to gems_auth;
grant update (password_hash, totp_secret_enc, totp_last_step) on app.app_user to gems_auth;
grant select, insert, update on app.app_session to gems_auth;
grant select, insert, update, delete on app.auth_throttle, app.auth_ip_attempt, app.auth_challenge,
  app.auth_recovery_code, app.auth_reset to gems_auth;
grant usage on sequence app.auth_ip_attempt_id_seq to gems_auth;
grant insert on app.audit_log to gems_auth;
grant usage on sequence app.audit_log_id_seq to gems_auth;
-- Secrets never leave the auth role: the runtime app role must not read hashes or TOTP secrets.
revoke select on app.app_user from gems_app, gems_job, gems_report_ro;
